(function(global){
'use strict';
if(global.noUiSlider && global.noUiSlider.create) return;

function number(v, fallback){var n=Number(v);return Number.isFinite(n)?n:fallback;}
function rangeValue(v, fallback){
  if(Array.isArray(v)) return number(v[0], fallback);
  if(v && typeof v==='object' && '0' in v) return number(v[0], fallback);
  return number(v, fallback);
}
function eventBase(name){return String(name||'').split('.')[0];}
function clamp(v,min,max){return Math.max(min,Math.min(max,v));}

function create(target, options){
  if(!target) throw new Error('noUiSlider target is required');
  if(target.noUiSlider) return target.noUiSlider;
  options=options||{};
  var listeners={};
  var disabled=false;
  var min=rangeValue(options.range&&options.range.min,0);
  var max=rangeValue(options.range&&options.range.max,100);
  var step=Math.abs(number(options.step,1))||1;
  var format=options.format||{to:function(v){return String(v);},from:function(v){return Number(v);}};
  var initial=Array.isArray(options.start)?options.start[0]:options.start;
  var value=clamp(number(initial,min),min,max);

  target.classList.add('noUi-target','noUi-ltr','noUi-horizontal');
  target.innerHTML='';
  var base=document.createElement('div'); base.className='noUi-base';
  var connects=document.createElement('div'); connects.className='noUi-connects';
  var connect=document.createElement('div'); connect.className='noUi-connect';
  var origin=document.createElement('div'); origin.className='noUi-origin';
  var handle=document.createElement('div'); handle.className='noUi-handle noUi-handle-lower'; handle.setAttribute('role','slider'); handle.tabIndex=0;
  var touch=document.createElement('div'); touch.className='noUi-touch-area'; handle.appendChild(touch);
  connects.appendChild(connect); base.appendChild(connects); origin.appendChild(handle); base.appendChild(origin); target.appendChild(base);

  var input=document.createElement('input');
  input.type='range'; input.className='noUi-native-range'; input.min=String(min); input.max=String(max); input.step=String(step); input.value=String(value);
  input.setAttribute('aria-label', target.getAttribute('aria-label')||'Slider');
  target.appendChild(input);

  function percent(){return max===min?0:((value-min)/(max-min))*100;}
  function formatted(){try{return format.to(value);}catch(e){return String(value);}}
  function paint(){
    var p=percent();
    connect.style.transform='translate(0,0) scale('+Math.max(0,p/100)+',1)';
    connect.style.transformOrigin='0 0';
    origin.style.transform='translate('+p+'%,0)';
    handle.setAttribute('aria-valuemin',String(min)); handle.setAttribute('aria-valuemax',String(max)); handle.setAttribute('aria-valuenow',String(value));
    input.min=String(min); input.max=String(max); input.step=String(step); input.value=String(value); input.disabled=disabled;
    target.classList.toggle('noUi-state-disabled',disabled);
  }
  function emit(type, handleIndex){
    var vals=[formatted()], raw=[value];
    Object.keys(listeners).forEach(function(key){
      if(eventBase(key)===type){listeners[key].slice().forEach(function(fn){try{fn(vals,handleIndex||0,raw,false,[0]);}catch(e){setTimeout(function(){throw e;},0);}});}
    });
  }
  function assign(v, fireSet){
    if(Array.isArray(v)) v=v[0];
    try{v=format.from(v);}catch(e){}
    v=number(v,value);
    v=Math.round(v/step)*step;
    value=clamp(v,min,max); paint(); emit('update',0);
    if(fireSet){emit('set',0);emit('change',0);}
  }
  function pointValue(ev){
    var rect=base.getBoundingClientRect();
    var x=(ev.touches&&ev.touches[0]?ev.touches[0].clientX:ev.clientX)-rect.left;
    return min+clamp(x/Math.max(1,rect.width),0,1)*(max-min);
  }
  function startDrag(ev){
    if(disabled) return; ev.preventDefault(); assign(pointValue(ev),false); emit('start',0); emit('slide',0);
    function move(e){e.preventDefault();assign(pointValue(e),false);emit('slide',0);}
    function up(e){document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);document.removeEventListener('touchmove',move);document.removeEventListener('touchend',up);emit('set',0);emit('change',0);emit('end',0);}
    document.addEventListener('mousemove',move,{passive:false});document.addEventListener('mouseup',up);
    document.addEventListener('touchmove',move,{passive:false});document.addEventListener('touchend',up);
  }
  base.addEventListener('mousedown',startDrag);base.addEventListener('touchstart',startDrag,{passive:false});
  input.addEventListener('input',function(){if(disabled)return;value=number(input.value,value);paint();emit('update',0);emit('slide',0);});
  input.addEventListener('change',function(){if(disabled)return;emit('set',0);emit('change',0);});
  handle.addEventListener('keydown',function(e){if(disabled)return;var delta=0;if(e.key==='ArrowLeft'||e.key==='ArrowDown')delta=-step;if(e.key==='ArrowRight'||e.key==='ArrowUp')delta=step;if(e.key==='Home'){assign(min,true);e.preventDefault();}else if(e.key==='End'){assign(max,true);e.preventDefault();}else if(delta){assign(value+delta,true);e.preventDefault();}});

  var api={
    options:{range:{min:min,max:max},step:step,start:[value]},
    on:function(name,fn){(listeners[name]||(listeners[name]=[])).push(fn);if(eventBase(name)==='update')setTimeout(function(){fn([formatted()],0,[value],false,[0]);},0);return api;},
    off:function(name,fn){if(!name){listeners={};return api;}Object.keys(listeners).forEach(function(key){if(key===name||eventBase(key)===eventBase(name)){if(fn)listeners[key]=listeners[key].filter(function(x){return x!==fn;});else delete listeners[key];}});return api;},
    get:function(){return formatted();},
    set:function(v){assign(v,true);return api;},
    updateOptions:function(next,fireSet){next=next||{};if(next.range){min=rangeValue(next.range.min,min);max=rangeValue(next.range.max,max);api.options.range={min:min,max:max};}if(next.step!=null){step=Math.abs(number(next.step,step))||step;api.options.step=step;}if(next.start!=null){assign(next.start,!!fireSet);}else{value=clamp(value,min,max);paint();emit('update',0);}return api;},
    disable:function(){disabled=true;paint();return api;},
    enable:function(){disabled=false;paint();return api;},
    destroy:function(){target.innerHTML='';target.classList.remove('noUi-target','noUi-ltr','noUi-horizontal','noUi-state-disabled');delete target.noUiSlider;},
    reset:function(){assign(api.options.start,true);return api;}
  };
  target.noUiSlider=api;paint();setTimeout(function(){emit('update',0);},0);return api;
}

global.noUiSlider={create:create};
})(window);
